import { useSendTransaction } from 'wagmi';
import { createDataSuffix } from '@base-attribution-os/core';
const { sendTransaction } = useSendTransaction();
sendTransaction({ dataSuffix: createDataSuffix({ codes: ['bc_abc123'] }) });

import { Wallet } from 'ethers';
import { withEthersAttribution } from '@base-attribution-os/ethers';
wallet.sendTransaction(withEthersAttribution({ to, data: '0x' }, { codes: ['bc_abc123'] }));

function createDataSuffix() { return '0x'; }
const dataSuffix = createDataSuffix({ codes: ['bc_abc123'] });
wallet.sendTransaction({ dataSuffix });
